INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$642519d7$SATQ$, NULL, NULL, $SATQ$10199-DC$SATQ$, $SATQ$disclosed$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Problem-Solving and Data Analysis$SATQ$, $SATQ$Q$SATQ$, $SATQ$Q.G.$SATQ$, $SATQ$Evaluating statistical claims: Observational studies and experiments $SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, NULL, $SATQ$<p class="stem_paragraph ">A polling agency recently surveyed 1,000 adults who were selected at random from a large city and asked each of the adults, &ldquo;Are you satisfied with the quality of air in the city?&rdquo; Of those surveyed, 78 percent responded that they were satisfied with the quality of air in the city. Based on the results of the survey, which of the following statements must be true?<ol class="list_upper_roman">
            <li class="list_paragraph ">Of all adults in the city, 78 percent are satisfied with the quality of air in the city.</li>
            <li class="list_paragraph ">If another 1,000 adults selected at random from the city were surveyed, 78 percent of them would report they are satisfied with the quality of air in the city.</li>
            <li class="list_paragraph ">If 1,000 adults selected at random from a different city were surveyed, 78 percent of them would report they are satisfied with the quality of air in the city.</li>
          </ol></p>
$SATQ$, $SATQ$[{"id":"a","content":"<p>None</p>\n"},{"id":"b","content":"<p>II only</p>\n"},{"id":"c","content":"<p>I and II only</p>\n"},{"id":"d","content":"<p>I and III only</p>\n"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, NULL, $SATQ$<p>Choice A is correct. Statement I need not be true. The fact that 78% of the 1,000 adults who were surveyed responded that they were satisfied with the air quality in the city does not mean that the exact same percentage of <span class="underline">all</span> adults in the city will be satisfied with the air quality in the city. Statement II need not be true because random samples, even when they are of the same size, are not necessarily identical with regard to percentages of people in them who have a certain opinion. Statement III need not be true for the same reason that statement II need not be true: results from different samples can vary. The variation may be even bigger for this sample since it would be selected from a different city. Therefore, none of the statements must be true.<p>Choices B, C, and D are incorrect because none of the statements must be true.</p></p>
$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ$Multiple Choice$SATQ$, $SATQ$Math$SATQ$, $SATQ${"questionId":"642519d7","external_id":null,"disclosed_item_id":"10199-DC","source":"disclosed","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"Q","domain":"Problem-Solving and Data Analysis","skill_cd":"Q.G.","skill_desc":"Evaluating statistical claims: Observational studies and experiments ","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":null,"stem":"<p class=\"stem_paragraph \">A polling agency recently surveyed 1,000 adults who were selected at random from a large city and asked each of the adults, &ldquo;Are you satisfied with the quality of air in the city?&rdquo; Of those surveyed, 78 percent responded that they were satisfied with the quality of air in the city. Based on the results of the survey, which of the following statements must be true?<ol class=\"list_upper_roman\">\n            <li class=\"list_paragraph \">Of all adults in the city, 78 percent are satisfied with the quality of air in the city.</li>\n            <li class=\"list_paragraph \">If another 1,000 adults selected at random from the city were surveyed, 78 percent of them would report they are satisfied with the quality of air in the city.</li>\n            <li class=\"list_paragraph \">If 1,000 adults selected at random from a different city were surveyed, 78 percent of them would report they are satisfied with the quality of air in the city.</li>\n          </ol></p>\n","answerOptions":[{"id":"a","content":"<p>None</p>\n"},{"id":"b","content":"<p>II only</p>\n"},{"id":"c","content":"<p>I and II only</p>\n"},{"id":"d","content":"<p>I and III only</p>\n"}],"keys":null,"correct_answer":["A"],"rationale":"<p>Choice A is correct. Statement I need not be true. The fact that 78% of the 1,000 adults who were surveyed responded that they were satisfied with the air quality in the city does not mean that the exact same percentage of <span class=\"underline\">all</span> adults in the city will be satisfied with the air quality in the city. Statement II need not be true because random samples, even when they are of the same size, are not necessarily identical with regard to percentages of people in them who have a certain opinion. Statement III need not be true for the same reason that statement II need not be true: results from different samples can vary. The variation may be even bigger for this sample since it would be selected from a different city. Therefore, none of the statements must be true.<p>Choices B, C, and D are incorrect because none of the statements must be true.</p></p>\n","answer_style":"Multiple Choice","section":"Math","image_count":0,"raw_list":{"updateDate":1691007959637,"pPcc":"SAT#Q","questionId":"642519d7","skill_cd":"Q.G.","score_band_range_cd":5,"skill_desc":"Evaluating statistical claims: Observational studies and experiments ","createDate":1691007959637,"program":"SAT","primary_class_cd_desc":"Problem-Solving and Data Analysis","ibn":"10199-DC","external_id":null,"primary_class_cd":"Q","uId":"7fe82974-5960-487e-8afa-a133607d106e","difficulty":"M"},"raw_detail":{"item_id":"10199-DC","section":"Math","prompt":"<p class=\"stem_paragraph \">A polling agency recently surveyed 1,000 adults who were selected at random from a large city and asked each of the adults, &ldquo;Are you satisfied with the quality of air in the city?&rdquo; Of those surveyed, 78 percent responded that they were satisfied with the quality of air in the city. Based on the results of the survey, which of the following statements must be true?<ol class=\"list_upper_roman\">\n            <li class=\"list_paragraph \">Of all adults in the city, 78 percent are satisfied with the quality of air in the city.</li>\n            <li class=\"list_paragraph \">If another 1,000 adults selected at random from the city were surveyed, 78 percent of them would report they are satisfied with the quality of air in the city.</li>\n            <li class=\"list_paragraph \">If 1,000 adults selected at random from a different city were surveyed, 78 percent of them would report they are satisfied with the quality of air in the city.</li>\n          </ol></p>\n","answer":{"style":"Multiple Choice","choices":{"a":{"body":"<p>None</p>\n"},"b":{"body":"<p>II only</p>\n"},"c":{"body":"<p>I and II only</p>\n"},"d":{"body":"<p>I and III only</p>\n"}},"correct_choice":"a","rationale":"<p>Choice A is correct. Statement I need not be true. The fact that 78% of the 1,000 adults who were surveyed responded that they were satisfied with the air quality in the city does not mean that the exact same percentage of <span class=\"underline\">all</span> adults in the city will be satisfied with the air quality in the city. Statement II need not be true because random samples, even when they are of the same size, are not necessarily identical with regard to percentages of people in them who have a certain opinion. Statement III need not be true for the same reason that statement II need not be true: results from different samples can vary. The variation may be even bigger for this sample since it would be selected from a different city. Therefore, none of the statements must be true.<p>Choices B, C, and D are incorrect because none of the statements must be true.</p></p>\n"}},"createDate":1691007959637,"updateDate":1691007959637}$SATQ$::jsonb, 1691007959637, 1691007959637),
    ($SATQ$65c49824$SATQ$, NULL, NULL, $SATQ$04778-DC$SATQ$, $SATQ$disclosed$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Problem-Solving and Data Analysis$SATQ$, $SATQ$Q$SATQ$, $SATQ$Q.B.$SATQ$, $SATQ$Percentages$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$spr$SATQ$, NULL, $SATQ$<p class="stem_paragraph ">A school district is forming a committee to discuss plans for the construction of a new high school. Of those invited to join the committee, 15% are parents of students, 45% are teachers from the current high school, 25% are school and district administrators, and the remaining 6 individuals are students. How many more teachers were invited to join the committee than school and district administrators?</p>
$SATQ$, NULL, $SATQ$["8"]$SATQ$::jsonb, NULL, $SATQ$<p>The correct answer is 8. The 6 students represent <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/65c49824/img_000_2e5c95c0.png" alt="open parenthesis, 100 minus 15, minus 45, minus 25, close parenthesis, percent, equals 15 percent"></span> of those invited to join the committee. If <span class="italic">x</span> people were invited to join the committee, then <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/65c49824/img_001_cbb6133d.png" alt="0 point 1 5 x, equals 6"></span>. Thus, there were <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/65c49824/img_002_e7bbd23b.png" alt="6 over, 0 point 1 5, equals 40"></span> people invited to join the committee. It follows that there were <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/65c49824/img_003_e478066f.png" alt="0 point 4 5 times 40, equals 18"></span> teachers and <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/65c49824/img_004_203ef90d.png" alt="0 point 2 5 times 40, equals 10 "></span> school and district administrators invited to join the committee. Therefore, there were 8 more teachers than school and district administrators invited to join the committee.</p>
$SATQ$, true, 5, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ$SPR$SATQ$, $SATQ$Math$SATQ$, $SATQ${"questionId":"65c49824","external_id":null,"disclosed_item_id":"04778-DC","source":"disclosed","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"Q","domain":"Problem-Solving and Data Analysis","skill_cd":"Q.B.","skill_desc":"Percentages","difficulty":"H","score_band_range_cd":6,"type":"spr","stimulus":null,"stem":"<p class=\"stem_paragraph \">A school district is forming a committee to discuss plans for the construction of a new high school. Of those invited to join the committee, 15% are parents of students, 45% are teachers from the current high school, 25% are school and district administrators, and the remaining 6 individuals are students. How many more teachers were invited to join the committee than school and district administrators?</p>\n","answerOptions":null,"keys":null,"correct_answer":["8"],"rationale":"<p>The correct answer is 8. The 6 students represent <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/65c49824/img_000_2e5c95c0.png\" alt=\"open parenthesis, 100 minus 15, minus 45, minus 25, close parenthesis, percent, equals 15 percent\"></span> of those invited to join the committee. If <span class=\"italic\">x</span> people were invited to join the committee, then <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/65c49824/img_001_cbb6133d.png\" alt=\"0 point 1 5 x, equals 6\"></span>. Thus, there were <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/65c49824/img_002_e7bbd23b.png\" alt=\"6 over, 0 point 1 5, equals 40\"></span> people invited to join the committee. It follows that there were <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/65c49824/img_003_e478066f.png\" alt=\"0 point 4 5 times 40, equals 18\"></span> teachers and <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/65c49824/img_004_203ef90d.png\" alt=\"0 point 2 5 times 40, equals 10 \"></span> school and district administrators invited to join the committee. Therefore, there were 8 more teachers than school and district administrators invited to join the committee.</p>\n","answer_style":"SPR","section":"Math","image_count":5,"raw_list":{"updateDate":1691007959628,"pPcc":"SAT#Q","questionId":"65c49824","skill_cd":"Q.B.","score_band_range_cd":6,"skill_desc":"Percentages","createDate":1691007959628,"program":"SAT","primary_class_cd_desc":"Problem-Solving and Data Analysis","ibn":"04778-DC","external_id":null,"primary_class_cd":"Q","uId":"087ac429-b4e9-4710-ba68-44de3444c68c","difficulty":"H"},"raw_detail":{"item_id":"04778-DC","section":"Math","prompt":"<p class=\"stem_paragraph \">A school district is forming a committee to discuss plans for the construction of a new high school. Of those invited to join the committee, 15% are parents of students, 45% are teachers from the current high school, 25% are school and district administrators, and the remaining 6 individuals are students. How many more teachers were invited to join the committee than school and district administrators?</p>\n","answer":{"style":"SPR","rationale":"<p>The correct answer is 8. The 6 students represent <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"open parenthesis, 100 minus 15, minus 45, minus 25, close parenthesis, percent, equals 15 percent\"></span> of those invited to join the committee. If <span class=\"italic\">x</span> people were invited to join the committee, then <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"0 point 1 5 x, equals 6\"></span>. Thus, there were <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"6 over, 0 point 1 5, equals 40\"></span> people invited to join the committee. It follows that there were <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"0 point 4 5 times 40, equals 18\"></span> teachers and <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"0 point 2 5 times 40, equals 10 \"></span> school and district administrators invited to join the committee. Therefore, there were 8 more teachers than school and district administrators invited to join the committee.</p>\n"}},"createDate":1691007959628,"updateDate":1691007959628,"correct_answer_extracted_from_rationale":true}$SATQ$::jsonb, 1691007959628, 1691007959628),
    ($SATQ$661dfddd$SATQ$, NULL, NULL, $SATQ$070913-DC$SATQ$, $SATQ$disclosed$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Problem-Solving and Data Analysis$SATQ$, $SATQ$Q$SATQ$, $SATQ$Q.D.$SATQ$, $SATQ$Two-variable data: Models and scatterplots$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, NULL, $SATQ$<p><img src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/661dfddd/img_000_ea0cebc0.png" alt="The figure presents a scatterplot titled &ldquo;Temperature and Elevation.&rdquo; The horizontal axis is labeled &ldquo;Elevation, in feet,&rdquo; and the numbers 6,000 through 9,000, in increments of 500, are indicated. The vertical axis is labeled &ldquo;Temperature, in degrees Fahrenheit,&rdquo; and the integers 37 through 45 are indicated. There are 8 data points. The data points begin a little below, and to the right of the top of the vertical axis, then trend downward and to the right. A line of best fit is drawn. The data represented by the 8 data points are as follows. Note that all values are approximate. Point 1. 6,350 feet, 42 point 9 degrees Fahrenheit. Point 2. 6,750 feet, 43 point 8 degrees Fahrenheit. Point 3. 6,750 feet, 42 degrees Fahrenheit. Point 4. 7,500 feet, 42 point 2 degrees Fahrenheit. Point 5. 8,000 feet, 40 point 5 degrees Fahrenheit. Point 6. 8,000 feet, 40 degrees Fahrenheit. Point 7. 8,800 feet, 38 point 6 degrees Fahrenheit. Point 8. 8,800 feet, 37 point 6 degrees Fahrenheit. The line of best fit passes through the data point representing 7,500 feet comma 41 point 1 degrees Fahrenheit, and the data point representing 8,500 feet comma 39 degrees Fahrenheit" width="212" height="167">
          <p class="stem_paragraph ">The scatterplot above shows the high temperature on a certain day and the elevation of 8 different locations in the Lake Tahoe Basin. A line of best fit for the data is also shown. Which of the following statements best describes the association between the elevation and the temperature of locations in the Lake Tahoe Basin?</p></p>
$SATQ$, $SATQ$[{"id":"a","content":"<p class=\"choice_paragraph \">As the elevation increases, the temperature tends to increase.</p>\n"},{"id":"b","content":"<p class=\"choice_paragraph \">As the elevation increases, the temperature tends to decrease.</p>\n"},{"id":"c","content":"<p class=\"choice_paragraph \">As the elevation decreases, the temperature tends to decrease.</p>\n"},{"id":"d","content":"<p class=\"choice_paragraph \">There is no association between the elevation and the temperature.</p>\n"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, NULL, $SATQ$<p>Choice B is correct. The association between the elevation and the temperature of locations in the Lake Tahoe Basin can be described by looking at the direction of the line of best fit. The line of best fit slopes downward, which&nbsp;corresponds to the temperature decreasing as the elevation increases.<p>Choices A and C are incorrect. Both of these choices would be represented by a line of best fit that slopes from the lower left to the upper right of the graph, which isn&rsquo;t what&rsquo;s shown on the graph. Choice D is incorrect. This choice would be represented by a line of best fit that is horizontal or has a slope very close to 0. This is not what&rsquo;s shown on the graph.</p></p>
